S = "Hakeem Force Academy"
QS = [
(S, "Who is regarded as the first Urdu poet to compile a Deewan (collection of ghazals)?", ["Wali Deccani", "Muhammad Quli Qutb Shah", "Mir Taqi Mir", "Mirza Ghalib"], 1, "Muhammad Quli Qutb Shah, the ruler of Golconda, compiled the first complete Deewan in Urdu.", "Wali Deccani is also called the father of Urdu ghazal, and sources differ on who deserves the title of first.", [4818]),
(S, "The Strait of Gibraltar connects the Mediterranean Sea with which water body?", ["Red Sea", "Atlantic Ocean", "Indian Ocean", "Black Sea"], 1, "The Strait of Gibraltar is a narrow channel between Spain and Morocco that joins the Mediterranean Sea to the Atlantic Ocean.", "The strait is only about 13 km wide at its narrowest point.", [1020]),
(S, "Which language, called Shina, is mainly spoken in Gilgit and nearby areas?", ["Balti", "Shina", "Burushaski", "Wakhi"], 1, "Shina is the main language of the Gilgit region and Diamer, and the language itself is named Shina.", "Burushaski is spoken in Hunza and Nagar and Balti in Baltistan.", [4136]),
(S, "Which article of the 1973 Constitution of Pakistan guarantees the right to free and compulsory education?", ["Article 25A", "Article 19", "Article 20", "Article 25"], 0, "Article 25A, added by the 18th Amendment in 2010, makes free and compulsory education a right for children aged 5 to 16.", "Article 25 deals with equality of citizens.", [3869, 714]),
(S, "Which is the largest glacier of Pakistan according to most Pakistani textbooks?", ["Baltoro Glacier", "Biafo Glacier", "Hispar Glacier", "Siachen Glacier"], 3, "Pakistani textbooks name the Siachen Glacier, about 76 km long, as the largest in the Karakoram and in the region.", "Sources differ because Siachen is under Indian control, and Biafo and Baltoro are the longest glaciers inside Pakistan-administered areas.", [1114, 732]),
(S, "Find the odd one out: Cow, goat, horse, buffalo.", ["Cow", "Goat", "Horse", "Buffalo"], 2, "Cow, goat and buffalo are ruminants that are kept for milk, but the horse is not a ruminant and is mainly used for riding and work.", "Ruminants chew the cud and have a stomach with four chambers.", [1724]),
(S, "The Gobi Desert lies in southern Mongolia and in which other country?", ["Russia", "China", "Kazakhstan", "India"], 1, "The Gobi Desert stretches across southern Mongolia and northern China.", "It is a cold desert and the largest desert in Asia.", [2149, 479]),
(S, "In which continent is the Cape of Good Hope located?", ["Asia", "Australia", "South America", "Africa"], 3, "The Cape of Good Hope is a rocky headland on the Atlantic coast of South Africa.", "Vasco da Gama rounded it in 1497 on the sea route to India.", [539]),
(S, "Choose the correct word: He was good ___ math.", ["in", "at", "for", "on"], 1, "The correct preposition after the adjective good, when talking about a skill or subject, is at.", "We also say bad at, clever at and expert at.", [841, 4360]),
(S, "What form of government was set up by the 1956 Constitution of Pakistan?", ["Presidential", "Military", "Parliamentary", "Confederal"], 2, "The 1956 Constitution made Pakistan an Islamic Republic with a parliamentary system, with a President as head of state and a Prime Minister as head of government.", "The 1962 Constitution changed this to a presidential system.", [690]),
(S, "Who served as the last Governor General of Pakistan and then became its first President?", ["Ghulam Muhammad", "Khawaja Nazimuddin", "Ayub Khan", "Iskander Mirza"], 3, "Iskander Mirza was Governor General from 1955 and became the first President when the 1956 Constitution came into force.", "He was removed in October 1958 after Ayub Khan took over.", [4370]),
(S, "Who is the current Governor of Punjab (Pakistan) as of October 2026?", ["Sardar Saleem Haider Khan", "Chaudhry Mohammad Sarwar", "Balighur Rehman", "Latif Khosa"], 0, "Sardar Saleem Haider Khan of the PPP took oath as Governor of Punjab on 10 May 2024 and was still in office in 2026.", "His predecessor was Balighur Rehman, and Latif Khosa served in 2024 before him.", [4506, 1345]),
(S, "Who was the first Governor of Sindh after the creation of Pakistan in 1947?", ["Ayub Khuhro", "Shaikh Din Muhammad", "Sir Ghulam Hussain Hidayatullah", "Sir Francis Mudie"], 2, "Sir Ghulam Hussain Hidayatullah was appointed by Quaid-e-Azam and served from August 1947 until he died in office in October 1948.", "His successor was Shaikh Din Muhammad, and Ayub Khuhro is known as a Chief Minister of Sindh.", [4680]),
(S, "In which country is the Great Pyramid located?", ["Iraq", "Sudan", "Egypt", "Jordan"], 2, "The Great Pyramid, built for Pharaoh Khufu, stands at Giza near Cairo in Egypt.", "It is the only one of the Seven Wonders of the Ancient World that still stands.", [3779]),
(S, "Which city is the most populous in the world according to the UN World Urbanization Prospects 2025?", ["Tokyo", "Delhi", "Jakarta", "Shanghai"], 2, "The UN 2025 report ranks Jakarta first with about 42 million people, ahead of Dhaka and Tokyo.", "Tokyo was named the largest city in earlier UN reports and has now dropped to third.", [3903]),
(S, "What is the capital of Greece?", ["Sparta", "Thessaloniki", "Athens", "Crete"], 2, "Athens is the capital and largest city of Greece.", "Athens hosted the first modern Olympic Games in 1896.", [3027]),
(S, "Which crop is grown on the largest area in Pakistan?", ["Rice", "Wheat", "Cotton", "Sugarcane"], 1, "Wheat is the main staple crop and is grown on the largest area of cultivated land in Pakistan.", "Wheat is a rabi crop sown in winter and harvested in spring.", [4001]),
(S, "Which body part of a human baby is almost fully grown (adult size) at birth?", ["Brain", "Heart", "Eyes", "Legs"], 2, "A baby's eyeballs are already close to adult size at birth, while other body parts keep growing.", "The eyes grow only a little during life.", [4115]),
(S, "In which Islamic month is Hajj performed?", ["Ramadan", "Rajab", "Muharram", "Dhul Hijjah"], 3, "Hajj is performed from the 8th to the 13th of Dhul Hijjah, the last month of the Islamic calendar.", "Eid ul Adha is celebrated on the 10th of Dhul Hijjah.", [544, 545]),
(S, "If 8 men can complete a piece of work in 6 days, how many men are needed to complete half of that work in the same 6 days?", ["2", "4", "6", "16"], 1, "Total work is 8 x 6 = 48 man-days, so half the work is 24 man-days. In 6 days this needs 24 / 6 = 4 men.", "Work done equals number of workers multiplied by days.", [1934]),
(S, "A car travels 60 km. A train with double the speed of the car travels for half the time. What distance does the train cover?", ["30 km", "60 km", "120 km", "90 km"], 1, "Distance = speed x time. Doubling the speed and halving the time gives 2 x 1/2 = 1 times the car's distance, which is 60 km.", "Speed doubled and time halved leaves the distance unchanged.", [234]),
]
